  );

  TEST_ASSERT(geom != NULL);
  TEST_CHECK(include_axis == gkyl_mirror_grid_gen_is_include_axis(geom));
  TEST_CHECK(fl_coord == gkyl_mirror_grid_gen_fl_coord(geom));

