      (int[]){3, 1, 1}
    );
    struct gkyl_range local, ext;
    gkyl_create_grid_ranges(&grid, (int[]){0, 0, 0}, &ext, &local);
    for (int kind = -2; kind < 3; ++kind) {
      struct gkyl_mirror_grid_gen_inp inp = {
